# Run from the package root after 35 and 38c:  Rscript data-raw/qa/38d_settings_text.R
# Writes the section "Other fixed settings" of data-raw/known_issues.md (between marker comments), every number computed from the saved results and the data.
suppressMessages({library(sf); library(dplyr)}); sf_use_s2(FALSE)
source("data-raw/qa/helpers.R")
for (f in list.files("data", pattern = "\\.rda$", full.names = TRUE)) load(f)
O <- readRDS(qa_out("other_settings.rds")); C <- readRDS(qa_out("pop_candidate_check.rds"))
f0 <- function(x) format(x, big.mark = ",", trim = TRUE); pc <- function(x, d = 1) sprintf(paste0("%.", d, "f%%"), x)
md_table <- function(d) paste(c(paste0("| ", paste(names(d), collapse = " | "), " |"), paste0("|", paste(rep("---", ncol(d)), collapse = "|"), "|"),
                                apply(d, 1, function(r) paste0("| ", paste(r, collapse = " | "), " |"))), collapse = "\n")
# ---- other fixed settings: block in known_issues.md ----------------------------------------------------
tt <- st_drop_geometry(tornado_tracks); mw <- O$min_width; ex <- O$extremes; sb <- O$state_buffer; rf <- O$radius_factor
# curvature of a straight lon/lat line in EPSG:5070 for the 25 longest tracks (the reason for the 5 km block margin)
top <- tornado_tracks[order(-tornado_tracks$len_mi), ][1:25, ]; top <- top[top$track_type == "line", ]
dev <- vapply(seq_len(nrow(top)), function(i) { m <- st_coordinates(st_geometry(top)[i])[, 1:2]; f <- seq(0, 1, length.out = 401)   # a straight line in longitude and latitude
  xy <- cbind(m[1, 1] + f * (m[2, 1] - m[1, 1]), m[1, 2] + f * (m[2, 2] - m[1, 2]))
  p5 <- st_coordinates(st_transform(st_sfc(st_multipoint(xy), crs = 4326), 5070))[, 1:2]; a <- p5[1, ]; bb <- p5[nrow(p5), ]
  u <- (bb - a) / sqrt(sum((bb - a)^2)); w <- t(t(p5) - a); max(abs(w[, 1] * u[2] - w[, 2] * u[1])) }, 0)
# observed numerical deviations behind the rounding tolerances
d <- tornado_exposure
dev_share <- max(abs(tapply(d$area_share_of_tornado, d$tornado_id, sum) - 1)); dev_pop <- max(d$pop_affected - d$zcta_pop); dev_prop <- max(d$pop_prop_affected, na.rm = TRUE) - 1
tot <- tapply(d$property_loss_tornado_total, d$tornado_id, function(x) x[1]); al <- tapply(d$property_loss_allocated, d$tornado_id, sum); kn <- !is.na(tot)
dev_loss <- max(abs(al[kn] - tot[kn]) / pmax(1, tot[kn]))
blk <- paste(c("<!-- fixed-settings:start -->", "## Other fixed settings", "",
  paste0("Each value below is fixed in the code. For each: what it is, the value, how it was chosen, and what it changes."), "",
  paste0("* **Minimum path width (10 yards).** When SPC records a width of 0 or none, the package uses 10 yards (9.1 m) so that the path has an area; 10 yards is the minimum width in SPC's older format description. This affects ", f0(mw$tornadoes[1]), " of ", f0(nrow(tt)), " tornadoes. SPC's older format description (<https://www.spc.noaa.gov/wcm/torforma.doc>) says: \"The minimum width is assumed to be 30 feet (ie = 3)\", which is 10 yards. The current database description (<https://www.spc.noaa.gov/wcm/data/SPC_severe_database_description.pdf>, a scanned document) gives the width in yards and states no minimum. SPC widths are whole yards: the smallest nonzero width is ", min(tt$wid_yd[!tt$width_imputed]), " yard and ", f0(sum(tt$wid_yd[!tt$width_imputed] == 10)), " tornadoes have exactly 10 yards. With 5, 10 or 20 yards these ", f0(mw$tornadoes[1]), " tornadoes have ", paste(f0(mw$zcta_pairs), collapse = ", "), " ZCTA rows, and ", f0(mw$tornadoes_with_a_zcta[2]), " of them have a ZCTA in each case; at 10 yards every one of their rows has `area_prop_affected` of 0.01 or less."),
  paste0("* **5 km margin when choosing census blocks (population).** The blocks a path covers are chosen in longitude and latitude, where a straight path drawn in the equal-area projection is curved; for the ", nrow(top), " line tracks among the 25 longest tracks the largest distance between the two is ", sprintf("%.2f", max(dev) / 1000), " km (median ", sprintf("%.2f", median(dev) / 1000), " km). Blocks within 5 km of the path are therefore taken as candidates, and the area of each block inside the path is then computed exactly, so the margin only has to be larger than that distance; a larger margin changes nothing except speed. Independent check: for ", C$tornadoes, " tornadoes (the ", C$n_longest, " longest paths, ", C$n_long, " random line tracks of 10 miles or more, ", C$n_short, " random shorter lines and ", C$n_point, " point tracks; these sample sizes are not tested choices) the residents computed with no candidate selection at all differ from the stored `pop_affected` by at most ", C$max_abs_diff, " residents (", C$n_differ, " of ", C$rows, " rows differ by more than 1e-6)."),
  paste0("* **10 km margin around state outlines.** Population is processed state by state, and the states a path touches are found from generalized state outlines widened by 10 km, because the outlines are generalized cartographic boundaries. In a sample of ", f0(sb$tornadoes), " tornadoes (the 100 longest and random others; the sample size is not a tested choice), ", sb$none_at_0, " paths touch no outline without the margin and ", sb$none_at_10km, " with it (", sb$differ_0_vs_10km, " paths pick up an additional, neighboring state, which only costs time). The ", sb$none_at_10km, " paths with no state within 10 km have no exposure rows."),
  paste0("* **1.05 factor on the search radius (`centroid_dist_km`).** The spatial index is searched with a buffer of 1.05 times the radius, and the exact distance is then computed for the candidates only. The factor guards against the polygon approximation of a circular buffer. For 200 random line tracks (a sample size that is not a tested choice), a radius of 5 km gives ", f0(rf$factor_1.00[1]), ", ", f0(rf$factor_1.05[1]), " and ", f0(rf$factor_1.50[1]), " ZCTA centroids within the radius with factors 1.00, 1.05 and 1.50, and a radius of 25 km gives ", f0(rf$factor_1.00[2]), ", ", f0(rf$factor_1.05[2]), " and ", f0(rf$factor_1.50[2]), ": without the margin ", rf$factor_1.05[2] - rf$factor_1.00[2], " centroid is missed, and a larger margin than 1.05 finds nothing more."),
  paste0("* **Sanity limits in the update checks.** `data-raw/update_data.R` stops for review when a new record has a path length above 400 miles, a latitude outside 15 to 72 or a longitude outside -180 to -60. These are guards against corrupt records, not scientific values. In the data the longest path is ", ex$max_len_mi, " miles (`", ex$longest_id, "`; ", ex$n_over_100_mi, " paths exceed 100 miles), latitudes run from ", ex$lat[1], " to ", ex$lat[2], " and longitudes from ", ex$lon[1], " to ", ex$lon[2], ". The same script stops for a width outside 0 to 10,000 yards (the largest width in the data is ", f0(max(tt$wid_yd)), " yards) and for known loss above 1e11 dollars (the largest in the data is ", f0(max(tt$property_loss_tornado_total, na.rm = TRUE)), " dollars)."),
  paste0("* **Rounding tolerances (1e-6 and 1e-9).** The integrity checks accept differences of up to 1e-6 residents between `pop_affected` and `zcta_pop`, and up to 1e-9 on shares and proportions (1e-8 relative on allocated loss). They only absorb floating-point rounding. In the data the largest excess of `pop_affected` over `zcta_pop` is ", format(dev_pop, digits = 3), " residents, the largest departure of a tornado's shares from a sum of 1 is ", format(dev_share, digits = 3), ", the largest `pop_prop_affected` minus 1 is ", format(dev_prop, digits = 3), ", and the largest relative difference between allocated loss and the tornado total is ", format(dev_loss, digits = 3), "."),
  "<!-- fixed-settings:end -->"), collapse = "\n")
p <- "data-raw/known_issues.md"; s <- paste0(paste(readLines(p, warn = FALSE), collapse = "\n"), "\n"); st_ <- "<!-- fixed-settings:start -->"; en <- "<!-- fixed-settings:end -->"
if (grepl(st_, s, fixed = TRUE)) { a <- regexpr(st_, s, fixed = TRUE); b2 <- regexpr(en, s, fixed = TRUE) + nchar(en); s <- paste0(substr(s, 1, a - 1), blk, substr(s, b2, nchar(s))) } else s <- paste0(s, "\n", blk, "\n")
writeLines(sub("\n+$", "", s), p)
cat("wrote the fixed-settings block of known_issues.md\n")
